```json
GET /nome_do_index/_search
{
  "_source": false,
  "query": {
    "bool": {
      "should": [
        { "exists": { "field": "estabe" } },
        { "term": { "estabe": "" }}
      ],
      "minimum_should_match": 1
    }
  },
